import type { Metadata } from "next";
import { SITE } from "@/lib/site";

export const absoluteUrl = (path: string) => `${SITE.url}${path === "/" ? "" : path}`;

// Google shows roughly 60–70 characters of a title.
const MAX_TITLE = 70;
// Generated by app/opengraph-image.tsx; set explicitly because a page's own
// openGraph object replaces the inherited one.
const SHARE_IMAGE = "/opengraph-image";

// Per-page metadata with a canonical URL and matching Open Graph / Twitter tags.
// Long titles drop the " | Growbard" suffix so they aren't cut off in results.
export function pageMetadata({
  title,
  description,
  path,
  type = "website",
}: {
  title: string;
  description: string;
  path: string;
  type?: "website" | "article";
}): Metadata {
  const fitsSuffix = `${title} | ${SITE.name}`.length <= MAX_TITLE;
  return {
    title: fitsSuffix ? title : { absolute: title },
    description,
    alternates: { canonical: path },
    openGraph: { title, description, url: path, type, siteName: SITE.name, locale: "en_BD", images: [SHARE_IMAGE] },
    twitter: { card: "summary_large_image", title, description, images: [SHARE_IMAGE] },
  };
}

export type Crumb = { label: string; href?: string };

export function breadcrumbLd(crumbs: Crumb[]) {
  const all = [{ label: "Home", href: "/" }, ...crumbs];
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: all.map((c, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: c.label,
      ...(c.href ? { item: absoluteUrl(c.href) } : {}),
    })),
  };
}

export function faqLd(faqs: { q: string; a: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    mainEntity: faqs.map((f) => ({
      "@type": "Question",
      name: f.q,
      acceptedAnswer: { "@type": "Answer", text: f.a },
    })),
  };
}

export function serviceLd({
  name,
  description,
  path,
  areaServed = "Bangladesh",
}: {
  name: string;
  description: string;
  path: string;
  areaServed?: string;
}) {
  return {
    "@context": "https://schema.org",
    "@type": "Service",
    name,
    description,
    url: absoluteUrl(path),
    serviceType: name,
    areaServed: { "@type": "AdministrativeArea", name: areaServed },
    provider: { "@type": "ProfessionalService", name: SITE.name, url: SITE.url, telephone: SITE.phone },
  };
}
